  ('laax-switzerland', '01F', 'Laax (Flims-Laax-Falera)', 'Switzerland', 'Europe''s freestyle capital', 'live', 'verified', 'northernLights', 'Switzerland & the Alps', '{"ski","adventure","family","entertainment","wellness","ultra","romance"}', '{"alpine","adventurous","dramatic"}', '{"essential","comfort","premier","luxury","ultra"}', null, 'emerging', '{"key_facts":["Flims-Laax-Falera run as one area by the Weisse Arena Group (since 1996), branded LAAX; Graubünden/Surselva","~224 km pistes (official Weisse Arena; J2Ski cites ~235 km - flagged), 28 lift facilities, ~70% of terrain above 2,000 m","Vorab glacier ~3,000 m top (lift-top ~3,018 m, summit 3,028 m); valley bases ~1,016-1,100 m","World''s largest halfpipe: ~200 m long x ~6.9 m high, since 2014/15 season (verified) - exceeds Olympic spec","Freestyle Academy = Europe''s first indoor freestyle hall (2010, ~2,000 m2, Laax-Murschetg): trampolines/airbags/ramps","LAAX OPEN = Europe''s largest snowboard event, annual since 2016 (successor to Burton European Open)","Snowparks led by NoName on Crap Sogn Gion (operator markets 5; German Wikipedia lists 4 - flagged)","rocksresort = Design Hotel apartment base at Murschetg gondola foot: 248 apartments, 8 restaurants, 6 bars, 9 shops; also Signina + Riders hotels","Waldwipfelpfad = world''s longest treetop walkway (1.56 km, opened 11 Jul 2021)","TWO federally designated in-area heli landing sites: Crap Sogn Gion + Vorabgletscher (FOCA/BAZL) - guided heli-ski genuinely servable","Own lift pass (not Magic Pass; no Ikon/Epic); reached via Chur rail hub + bus; Zurich ~1.5-2 hr (verify)"],"safety":{"emergency":"112 / 117 police / 118 fire / 144 ambulance / 1414 REGA alpine air-rescue / 145 poison","hospital":"Chur (Kantonsspital Graubünden) ~30-40 min; local practice for day cases; REGA 1414 alpine evac","malaria":"none","yellow_fever":"not required","activity_note":"Freestyle-park + glacier terrain — park injuries (jumps/6.9 m pipe walls: ride within level, helmet+back protection, progress on Freestyle Academy airbag) AND avalanche off-piste: SLF five-level bulletin (slf.ch/White Risk; SLF HQ is in Davos, same canton), transceiver/shovel/probe + guide off-piste, glacier roped-and-guided; heli legal at 2 designated in-area sites (guided); rescue REGA 1414","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/switzerland","read":"2026-08-20T14:48:00Z","page_updated":"2026-08-11T10:23:45+01:00","source_country":"switzerland","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely"},"timing":{"peak":"High winter — Christmas/NY, Feb half-terms, Easter — plus the LAAX OPEN week","shoulder":"Early Dec opening + spring glacier skiing (Vorab holds late); summer hiking/biking + treetop-walk window","green":"Late Apr-Jun + Oct-Nov (some lifts/hotels close for maintenance — verify)","booking_lead":"Christmas/NY + Feb + Easter + LAAX OPEN 3-8 mo; regular winter 2-4 mo; summer 1-3 mo","off_season_specials":"Summer hiking/biking + treetop walkway (Jun-Sep); spring-ski value; Freestyle Academy indoor all-weather year-round","event_peaks":"Ski holidays (~Dec-Apr), LAAX OPEN (winter — confirm dates), Christmas/NY","fire_date":"Next winter + freestyle/park weeks by Jun-Sep; LAAX OPEN + spring-ski from autumn/Jan; summer + treetop from spring"},"jewels":[{"name":"Ski all 224 km of Flims-Laax-Falera on one pass","si_tag":"Winter/Ski","status":"live","tier":"comfort","price_band":"lift pass to confirm; instructor ~CHF 350-550/day (approx)","timing":"ski season ~Dec-Apr; verify","draw_rank":1,"hook":"three villages run as one big, snow-sure Graubünden area on a single LAAX ticket","si":"ski","blurb":"three villages run as one big, snow-sure Graubünden area on a single LAAX ticket","when":"ski season ~Dec-Apr; verify","commission":"school/operator 10-15%","wells":["stay","activities"],"wells_basis":"derived from name/blurb/hook","si_all":["ski"],"shelf_fit